<?php declare(strict_types=1);
use PHPUnit\Framework\TestCase;
final class DependenciasPartidaTest extends TestCase {
 private function runProbe(string $file):string { $cmd=[PHP_BINARY,__DIR__.'/'.$file];$process=proc_open($cmd,[1=>['pipe','w'],2=>['pipe','w']],$pipes);self::assertIsResource($process);$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$code=proc_close($process);self::assertSame(0,$code,$out.$err);self::assertSame('',$err);return $out; }
 public function testSystemDoceCasosBase():void {$r=json_decode($this->runProbe('ensayo_base.php'),true,512,JSON_THROW_ON_ERROR);self::assertTrue($r['success']);self::assertCount(12,$r['cases']);foreach($r['cases'] as $c)self::assertTrue($c['matches_expected'],$c['case']);}
 public function testSystemOncePrecedenciasSinCambiarEsperado():void {$lines=explode("\n",trim($this->runProbe('ensayo_precedencias.php')));self::assertCount(11,$lines);$failedOld=[];foreach($lines as $line){$c=json_decode($line,true,512,JSON_THROW_ON_ERROR);self::assertTrue($c['pasa'],$c['caso']);if($c['propuesta_anterior']!==$c['esperado'])$failedOld[]=$c['caso'];}self::assertSame(['precedencia_primero','columns_true_vs_defs_false'],$failedOld);}
 public function testAdministradorOchoCasosEquivalentes():void {$lines=explode("\n",trim($this->runProbe('ensayo_secciones.php')));self::assertCount(8,$lines);foreach($lines as $line){$c=json_decode($line,true,512,JSON_THROW_ON_ERROR);self::assertTrue($c['pasa_corregido'],$c['caso']);self::assertSame($c['salidas']['original'],$c['salidas']['corregido']);}}
 public function testFallbackContratoDesconocidoConservaSalidaGetErrores():void {$r=json_decode($this->runProbe('ensayo_fallback.php'),true,512,JSON_THROW_ON_ERROR);self::assertTrue($r['success']);self::assertCount(27,$r['cases']);foreach($r['cases'] as $c)self::assertTrue($c['equal'],$c['case']);$base=json_decode($this->runProbe('ensayo_compatible_base.php'),true,512,JSON_THROW_ON_ERROR);self::assertTrue($base['success']);self::assertCount(12,$base['cases']);$lines=explode("\n",trim($this->runProbe('ensayo_compatible_precedencias.php')));self::assertCount(11,$lines);foreach($lines as $line)self::assertTrue(json_decode($line,true,512,JSON_THROW_ON_ERROR)['pasa']);}
}
